// Matches JSON-style env references like `${VAR_NAME}`.
const JSON_ENV_VAR_REGEX = /\$\{(\w+)\}/g;

// Matches YAML-style references like `${{ secrets.VAR_NAME }}` and
// `${{ inputs.VAR_NAME }}`.
const YAML_SECRET_INPUT_REGEX =
  /\$\{\{\s*(?:secrets|inputs)\.([^}\s]+)\s*\}\}/g;

function convertEnvJsonToYaml(
  env: Record<string, string>,
): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(env)) {
    result[key] = String(value).replace(
      JSON_ENV_VAR_REGEX,
      (_match, name) => `\${{ secrets.${name} }}`,
    );
  }
  return result;
}

function convertEnvYamlToJson(
  env: Record<string, string>,
): Record<string, string> {
  const result: Record<string, string> = {};
  for (const [key, value] of Object.entries(env)) {
    result[key] = String(value).replace(
      YAML_SECRET_INPUT_REGEX,
      (_match, name) => `\${${name}}`,
    );
  }
  return result;
}

