 * Convert a single JSON-style MCP server config into a YAML-style config.
 */
export function convertJsonMcpConfigToYamlMcpConfig(
  name: string,
  jsonConfig: JsonMcpServer,
): ConvertJsonMcpConfigToYamlMcpConfigResult {
  const warnings: string[] = [];
  const config = jsonConfig as Partial<
    StdioJsonMcpServer & SseJsonMcpServer & HttpJsonMcpServer
  >;

  const isStdio = config.command !== undefined || config.type === "stdio";
  const isRemote = config.url !== undefined;

  if (isStdio) {
    if (config.envFile !== undefined) {
      warnings.push("envFile is not supported");
    }

    const yamlConfig: MCPServer = {
      name,
      type: "stdio",
      command: config.command as string,
    };
    if (config.args !== undefined) {
      yamlConfig.args = config.args;
    }
    if (config.env !== undefined) {
      yamlConfig.env = convertEnvJsonToYaml(config.env);
    }

    return { yamlConfig, warnings };
