    const requestOptions =
      config.headers !== undefined
        ? { headers: config.headers }
        : undefined;

    if (config.type === "sse") {
      const yamlConfig: MCPServer = { name, url: config.url as string };
      if (requestOptions) {
        yamlConfig.requestOptions = requestOptions;
      }
      return { yamlConfig, warnings };
    }

